    public static int ctLine(emon.Port.Cells wd, emon.Port.Cells ln, emon.Port.Cells et, byte[] b, int x, int y) {
        // One line on page 1 from x at y: the words of b (split at spaces) 3000 apart, 2250 wide, 1100 tall, in 11 pt type.
        int w0 = Evidence.wdCount(wd);
        int n = emon.Port.blobLen(b);
        int y1 = y + 1100;
        int s = 0;
        int k = 0;
        int i = 0;
        int xe = x;
        while (k <= n) {
            if ((k == n) || (emon.Port.blobU8(b, k) == 32)) {
                if (k > s) {
                    int ts = emon.Port.cellsLen(et);
                    int wx = x + (i * 3000);
                    int wx1 = wx + 2250;
                    Model.textAppendUtf8(et, b, s, k);
                    int tl = emon.Port.cellsLen(et) - ts;
                    int r = Evidence.wdNew(wd, 1, wx, y, wx1, y1, wx, y1 - 200, wx1, y1 - 200, 0, 0, ts, tl, -1, -1, -1);
                    Evidence.wdSet(wd, r, Evidence.wfSize(), 1100);
                    Evidence.wdSet(wd, r, Evidence.wfFont(), 0);
                    xe = wx1;
                    i += 1;
                }
                s = k + 1;
            }
            k += 1;
        }
        Evidence.lnNew(ln, 1, x, y, xe, y1, x, y1 - 200, xe, y1 - 200, 0, 0, w0, Evidence.wdCount(wd) - w0);
        return 0;
    }
    public static int ctPage(emon.Port.Cells wd, emon.Port.Cells et, emon.Port.Cells ln, emon.Port.Cells gfl, int marks) {
        // The fragments the column stage writes for page 1 of the evidence: `lc-copy`, the boxes of the graphics layer (when `marks` is 1) and `lc-page`. Answers how many; the rows of `cf`
        // are in the scratch `cf` the caller reads, so this answers the count of the first and the role of the last in one number: fragments * 10 + the last fragment's role.
        emon.Port.Cells lt = emon.Port.newCells();
        emon.Port.Cells ls = emon.Port.newCells();
        emon.Port.Cells sd = emon.Port.newCells();
        emon.Port.Cells it = emon.Port.newCells();
        emon.Port.Cells io = emon.Port.newCells();
        emon.Port.Cells rw = emon.Port.newCells();
        emon.Port.Cells gu = emon.Port.newCells();
        emon.Port.Cells ac = emon.Port.newCells();
        emon.Port.Cells tm = emon.Port.newCells();
        emon.Port.Cells cf = emon.Port.newCells();
        emon.Port.Cells lo = emon.Port.newCells();
        emon.Port.Cells pr = emon.Port.newCells();
        emon.Port.Cells pages = emon.Port.newCells();
        int i = 0;
        int n = 0;
        Model.pageNew(pages, 1, 61200, 79200, 0, Model.pkVector());
        Columns.lcCopy(ln, lt);
        if (marks == 1) {
            Columns.lcMarkAsides(lt, gfl, pages, 1);
        }
        while (i < Evidence.lnCount(lt)) {
            emon.Port.cellsPush(ls, i);
            i += 1;
        }
        n = Columns.lcPage(wd, et, lt, 1, ls, sd, it, io, rw, gu, ac, tm, cf, lo, pr);
        return (n * 10) + emon.Port.cellsAt(cf, ((n - 1) * Columns.lcCfStride()) + 3);
    }
    public static void testTwoBlocksOfShortLinesFarApartAreTwoColumns() {
        emon.Port.Cells wd = emon.Port.newCells();
        emon.Port.Cells ln = emon.Port.newCells();
        emon.Port.Cells et = emon.Port.newCells();
        emon.Port.Cells gfl = emon.Port.newCells();
        // D583 (smoke review A issue 14): an invoice's two blocks, Seller and Client, 238 pt apart, with 1 to 3 words a line (2.3 and 2.6 a line on average, short of three): two columns, not
        // lines that alternate. (The roles are body, body: the last fragment's role is 0.)
        ctLine(wd, ln, et, emon.Testport.textBlob("Seller:"), 7200, 10000);
        ctLine(wd, ln, et, emon.Testport.textBlob("Client:"), 40000, 10000);
        ctLine(wd, ln, et, emon.Testport.textBlob("Dunn Campbell"), 7200, 11400);
        ctLine(wd, ln, et, emon.Testport.textBlob("Ramirez Donaldson Lane"), 40000, 11400);
        ctLine(wd, ln, et, emon.Testport.textBlob("36709 Santiago Viaduct"), 7200, 12800);
        ctLine(wd, ln, et, emon.Testport.textBlob("567 Ortiz Valley"), 40000, 12800);
        ctLine(wd, ln, et, emon.Testport.textBlob("Dianaland MN 12512"), 7200, 14200);
        ctLine(wd, ln, et, emon.Testport.textBlob("Kellyfort GA 69454"), 40000, 14200);
        ctLine(wd, ln, et, emon.Testport.textBlob("Tax Id 986-74-6578"), 7200, 17000);
        ctLine(wd, ln, et, emon.Testport.textBlob("Tax Id 948-74-8143"), 40000, 17000);
        ctLine(wd, ln, et, emon.Testport.textBlob("IBAN GB37QZVP50159087754233"), 7200, 18400);
        emon.Testport.assertEq(ctPage(wd, et, ln, gfl, 0), 20 + Model.rlBody(), "two body fragments");
    }
